function KeyLab.GearLootDatabase.GetItemsForSpecDungeon(specID, mapID)
    local ids = KeyLab.GearLootDatabase.bySpec and KeyLab.GearLootDatabase.bySpec[specID] and KeyLab.GearLootDatabase.bySpec[specID][mapID]
    local out = {}
    if not ids then return out end
    for _, itemID in ipairs(ids) do
        local item = KeyLab.GearLootDatabase.items[itemID]
        if item then table.insert(out, item) end
    end
    return out
end

function KeyLab.GearLootDatabase.GetSeasonInfo()
    return KeyLab.GearLootDatabase.expansion, KeyLab.GearLootDatabase.season, KeyLab.GearLootDatabase.seasonName
end
